SELECT 'governance_objects' AS rule,ABS(2-(SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('institution_recovery','institution_recovery_approval')))+ABS(8-(SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME LIKE 'mt5gov_%')) AS violations
UNION ALL SELECT 'recovery_request_owner',COUNT(*) FROM institution_recovery r LEFT JOIN institution_invitation i ON i.institution_id=r.institution_id AND i.id=r.id LEFT JOIN institution_onboarding_event e ON e.institution_id=r.institution_id AND e.id=r.request_event_id WHERE i.id IS NULL OR i.kind<>'Recovery' OR i.recipient_user_id<>r.recipient_user_id OR e.id IS NULL OR e.actor_kind<>'Operator' OR e.action<>'RecoveryRequested'
UNION ALL SELECT 'recovery_approval_actor',COUNT(*) FROM institution_recovery_approval a LEFT JOIN institution_onboarding_event e ON e.institution_id=a.institution_id AND e.id=a.event_id WHERE e.id IS NULL OR e.actor_kind<>'Operator' OR e.operator_id<>a.operator_id OR e.action<>'RecoveryApproved'
UNION ALL SELECT 'recovery_excess_approvals',COUNT(*) FROM (SELECT institution_id,recovery_id FROM institution_recovery_approval GROUP BY institution_id,recovery_id HAVING COUNT(*)>2) a
UNION ALL SELECT 'recovery_consumed_without_approvals',COUNT(*) FROM institution_recovery r JOIN institution_invitation i ON i.institution_id=r.institution_id AND i.id=r.id WHERE i.status='consumed' AND (SELECT COUNT(*) FROM institution_recovery_approval a WHERE a.institution_id=r.institution_id AND a.recovery_id=r.id)<>2;
